{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Dapagliflozin, which shares the identical ethoxyphenyl-chlorobenzyl aglycone with the query, has an absolute oral bioavailability of 78% (90% CI 73–83%) in healthy volunteers using an IV microdose method, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Empagliflozin, a close SGLT2 inhibitor analog, has an absolute oral bioavailability of 90% in humans, supporting high oral bioavailability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Tofogliflozin, another SGLT2 inhibitor with a similar C-aryl glycoside core, has an absolute oral bioavailability of 97.5% in humans, confirming the class-level high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Bexagliflozin, a recently approved SGLT2 inhibitor, has an absolute oral bioavailability of about 78% in humans, further supporting high F for the class.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a C-aryl glycoside SGLT2 inhibitor closely related to dapagliflozin. Multiple direct absolute bioavailability measurements in humans for dapagliflozin (78%), empagliflozin (90%), tofogliflozin (97.5%), and bexagliflozin (78%) all support F ≥ 20%. No transferable evidence indicates low bioavailability; therefore the prediction is high.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact bicyclic sugar modification in the query.",
    "The effect of the dioxabicyclo sugar ring on absorption, stability, or first-pass metabolism is not directly measured, though no evidence suggests it would reduce F below 20%.",
    "Most evidence comes from SGLT2 inhibitors with standard glucoside moieties; the query's modified sugar is not represented in the evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

